"""Writing generated files."""
import re

GENERATED = "Generated by ~/.config/hypr/scripts/themegen.py, do not edit by hand."


def write(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.is_symlink():
        path.unlink()
    path.write_text(text)


def write_bytes(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)


def without_block(text, begin, end):
    """text without the block from the marker line begin to the marker line end."""
    return re.sub(rf"{re.escape(begin)}.*?{re.escape(end)}\n?", "", text, flags=re.S)


def with_block(text, begin, end, block_lines):
    """text with the marked block rewritten at its end; everything outside the block stays."""
    text = without_block(text, begin, end)
    if text and not text.endswith("\n"):
        text += "\n"
    return text + "\n".join([begin, *block_lines, end]) + "\n"
